tape( 'the function throws an error if provided a fourth argument which does not have the same shape as the first argument', function test( t ) {
	var values;
	var x;
	var i;

	x = zeros( [ 3, 3, 3 ], {
		'dtype': 'float64'
	});
	values = [
		zeros( [ 3 ] ),
		zeros( [ 3, 3 ] ),
		zeros( [ 3, 3, 2 ] ),
		zeros( [ 2, 3, 3 ] ),
		zeros( [ 3, 3, 3, 3 ] )
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), Error, 'throws an error when provided an ndarray having shape (' + join( getShape( values[ i ] ), ',' ) + ')' );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			assign( x, [ 0, 0, 0 ], 5, value );
		};
	}
});

tape( 'the function does not modify the output ndarray if provided invalid indices', function test( t ) {
	var expected;
	var out;
	var x;

	x = array( [ [ 1.0, 2.0 ], [ 3.0, 4.0 ] ] );
	out = zeros( [ 2, 2 ], {
		'dtype': 'generic'
	});
	expected = [ [ 0.0, 0.0 ], [ 0.0, 0.0 ] ];

	t.throws( badValue( [ 2, 0 ] ), RangeError, 'throws an error when provided [2,0]' );
	t.deepEqual( ndarray2array( out ), expected, 'returns expected value' );

	t.throws( badValue( [ 0, '1' ] ), TypeError, 'throws an error when provided [0,\'1\']' );
	t.deepEqual( ndarray2array( out ), expected, 'returns expected value' );

	t.end();

	function badValue( value ) {
		return function badValue() {
			assign( x, value, 5.0, out );
		};
	}
});

tape( 'the function copies elements from an input ndarray to an output ndarray and replaces the element at a specified index with a provided value', function test( t ) {
	var expected;
	var out;
	var x;
	var y;

	x = array( [ [ 1.0, 2.0 ], [ 3.0, 4.0 ] ] );

	y = emptyLike( x );
	out = assign( x, [ 0, 0 ], 5.0, y );
	expected = [ [ 5.0, 2.0 ], [ 3.0, 4.0 ] ];
	t.strictEqual( out, y, 'returns expected value' );
	t.deepEqual( ndarray2array( out ), expected, 'returns expected value' );
	t.strictEqual( x.get( 0, 0 ), 1.0, 'returns expected value' );

	y = emptyLike( x );
	out = assign( x, [ 0, 1 ], 5.0, y );
	expected = [ [ 1.0, 5.0 ], [ 3.0, 4.0 ] ];
	t.strictEqual( out, y, 'returns expected value' );
	t.deepEqual( ndarray2array( out ), expected, 'returns expected value' );
	t.strictEqual( x.get( 0, 1 ), 2.0, 'returns expected value' );

	y = emptyLike( x );
	out = assign( x, [ 1, 1 ], 5.0, y );
	expected = [ [ 1.0, 2.0 ], [ 3.0, 5.0 ] ];
	t.strictEqual( out, y, 'returns expected value' );
	t.deepEqual( ndarray2array( out ), expected, 'returns expected value' );
	t.strictEqual( x.get( 1, 1 ), 4.0, 'returns expected value' );

	t.end();
});
